import {READ_SYNC_COPY,READ_SYNC_ROLES,createReadSyncDemo} from './shared/read-sync-demo.js?v=5.34.0';
import {brandMark} from './shared/brand.js?v=5.34.0';
import {esc} from './shared/core.js?v=5.34.0';
export function readSyncShell(lang){const c=READ_SYNC_COPY[lang]||READ_SYNC_COPY.en;return `<section id="read-sync-demo" class="read-sync-demo" aria-labelledby="read-sync-title"><div data-read-sync><h3 id="read-sync-title">${esc(c.title)}</h3><p>${esc(c.intro)}</p></div></section>`;}
export function readSyncMarkup(c,state,playing=false){const v=state.view(),request=v.role==='owner'||v.role==='floor',event=request?c.request:c.approval,server=v.server==='read'?c.serverRead:c.serverWait,other=v.other==='read'?c.otherRead:v.step===3?c.otherWait:c.otherUnread;return `<header class="sync-heading"><div><span class="sync-eyebrow">RAMI · READ SYNC DEMO</span><h3 id="read-sync-title">${esc(c.title)}</h3><p>${esc(c.intro)}</p></div><div class="sync-rami">${brandMark(v.online?'greeting':'thinking',true)}</div></header><p class="sync-boundary">${esc(c.boundary)}</p><div class="sync-role-label">${esc(c.roleLabel)}</div><div class="sync-roles" role="group" aria-label="${esc(c.roleLabel)}">${READ_SYNC_ROLES.map(role=>`<button type="button" data-sync-role="${role}" aria-pressed="${v.role===role}">${esc(c[role])}</button>`).join('')}</div><div class="sync-story" role="status" aria-live="polite" aria-atomic="true"><span>${String(v.step+1).padStart(2,'0')} / 05</span><strong>${esc(c.steps[v.step])}</strong></div><div class="sync-stages" aria-label="${esc(c.roleLabel)}"><article class="sync-device"><div class="sync-card-top"><span>01</span><b>${esc(c.old)}</b></div><div class="sync-screen"><span class="sync-network ${v.online?'is-online':'is-offline'}">${esc(v.online?c.online:c.offline)}</span><strong>${esc(c[v.role])}</strong><p>${esc(event)}</p><div class="sync-receipt is-read"><i aria-hidden="true">✓</i><span>${esc(c.oldRead)}</span></div>${v.queued?`<small>${esc(v.step===1?c.steps[1]:c.steps[2])}</small>`:''}</div></article><div class="sync-bridge" aria-hidden="true"><span>→</span></div><article class="sync-cloud"><div class="sync-card-top"><span>02</span><b>${esc(c.server)}</b></div><div class="sync-cloud-icon" aria-hidden="true"><svg viewBox="0 0 64 64" fill="none"><rect x="9" y="14" width="46" height="15" rx="5"/><rect x="9" y="35" width="46" height="15" rx="5"/><path d="M17 21.5h2M17 42.5h2M28 21.5h18M28 42.5h18"/></svg></div><p class="sync-server-status ${v.server==='read'?'is-read':''}">${esc(server)}</p></article><div class="sync-bridge" aria-hidden="true"><span>→</span></div><article class="sync-device"><div class="sync-card-top"><span>03</span><b>${esc(c.other)}</b></div><div class="sync-screen"><span class="sync-network is-online">${esc(c.online)}</span><strong>${esc(c[v.role])}</strong><p>${esc(event)}</p><div class="sync-receipt ${v.other==='read'?'is-read':'is-wait'}"><i aria-hidden="true">${v.other==='read'?'✓':'•'}</i><span>${esc(other)}</span></div></div></article></div><div class="sync-controls"><button class="sync-next" data-sync-next type="button" ${v.step===4?'disabled':''}>${esc(v.step===4?c.complete:c['next'+v.step])}<span aria-hidden="true">→</span></button><button data-sync-play type="button">${esc(playing?c.pause:c.play)}</button><button data-sync-reset type="button">${esc(c.reset)}</button></div><p class="sync-footnote">${esc(c.notice)}</p>`;}
export function bindReadSyncDemo(root,lang){if(!root)return ()=>{};const host=root.querySelector('[data-read-sync]'),c=READ_SYNC_COPY[lang]||READ_SYNC_COPY.en,state=createReadSyncDemo();let playing=false,timer=null,disposed=false;
 function stop(){playing=false;clearTimeout(timer);timer=null;}
 function draw(focus){if(disposed)return;host.innerHTML=readSyncMarkup(c,state,playing);if(focus)host.querySelector(focus)?.focus({preventScroll:true});}
 function tick(){if(!playing||disposed)return;timer=setTimeout(()=>{if(!playing||disposed)return;state.next();if(state.step===4)stop();const focus=host.querySelector('[data-sync-play]')===document.activeElement?'[data-sync-play]':null;draw(focus);tick();},1500);}
 function click(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.syncRole){stop();state.select(b.dataset.syncRole);draw('[data-sync-role="'+b.dataset.syncRole+'"]');return;}if(b.hasAttribute('data-sync-next')){stop();state.next();draw(state.step===4?'[data-sync-reset]':'[data-sync-next]');return;}if(b.hasAttribute('data-sync-reset')){stop();state.reset();draw('[data-sync-reset]');return;}if(b.hasAttribute('data-sync-play')){if(playing)stop();else{if(state.step===4)state.reset();playing=true;tick();}draw('[data-sync-play]');}}
 host.addEventListener('click',click);draw();return ()=>{disposed=true;stop();host.removeEventListener('click',click);};}
